//! Rust-owned Python and Go remote facade emitters.
//!
//! The protobuf stubs remain mechanical implementation details. These
//! facades own endpoint normalization, credential construction, and the
//! default secure transport policy so consumers do not select a platform
//! feature flag or instantiate a generated channel themselves.

use super::facade_operations;
use crate::{
    family_registry::FAMILY_VIEWS,
    transport::TransportKind,
};

pub(super) fn render_python(binding: &str) -> String {
    let mut output = format!(
        "# Generated by acyclic-sdk-contract-wire; do not edit.\n# rust_policy_source_binding: {binding}\n\n"
    );
    output.push_str(
        r###"from __future__ import annotations

from dataclasses import dataclass
from urllib.parse import urlsplit

import grpc

from .generated.actors.v1 import actors_pb2_grpc
from .generated.filesystem.v2 import filesystem_pb2_grpc
from .generated.harness.v2 import harness_pb2_grpc
from .generated.inference.v1 import inference_pb2_grpc
from .generated.machines.v1 import machines_pb2_grpc
from .generated.objects.v2 import objects_pb2_grpc
from .generated.stream.v2 import stream_pb2_grpc
from .generated.workers.v1 import workers_pb2_grpc


SOURCE_BINDING = "#BINDING#"
BEST_TRANSPORT = "grpc+tls"


@dataclass(frozen=True)
class Credentials:
    """Credentials accepted by the generated remote facade.

    A zero-value credential uses the platform trust store. Supplying a client
    certificate enables mTLS; bearer credentials are attached by gRPC call
    credentials and never need to be copied into individual RPC calls.
    """

    bearer_token: str | None = None
    root_certificates: bytes | None = None
    certificate_chain: bytes | None = None
    private_key: bytes | None = None

    @classmethod
    def bearer(cls, token: str) -> "Credentials":
        return cls(bearer_token=token)

    @classmethod
    def mtls(
        cls,
        certificate_chain: bytes,
        private_key: bytes,
        root_certificates: bytes | None = None,
        bearer_token: str | None = None,
    ) -> "Credentials":
        return cls(
            bearer_token=bearer_token,
            root_certificates=root_certificates,
            certificate_chain=certificate_chain,
            private_key=private_key,
        )


@dataclass(frozen=True)
class InferenceServices:
    models: inference_pb2_grpc.ModelsServiceStub
    contexts: inference_pb2_grpc.ContextsServiceStub
    warm_contexts: inference_pb2_grpc.WarmContextsServiceStub
    runs: inference_pb2_grpc.RunsServiceStub
    evaluations: inference_pb2_grpc.EvaluationsServiceStub


def _target(endpoint: str) -> tuple[str, bool]:
    value = str(endpoint).strip()
    if not value:
        raise ValueError("endpoint must not be empty")
    parsed = urlsplit(value if "://" in value else f"https://{value}")
    if parsed.scheme in ("https", "grpcs"):
        secure = True
    elif parsed.scheme in ("http", "grpc"):
        secure = False
    else:
        raise ValueError(f"unsupported endpoint scheme: {parsed.scheme}")
    target = parsed.netloc or parsed.path
    if not target or parsed.path not in ("", "/") and parsed.netloc:
        raise ValueError("endpoint must contain only an authority")
    return target, secure


def _validate(credentials: Credentials, secure: bool) -> None:
    token = credentials.bearer_token
    if token is not None and (not token.strip() or "\n" in token or "\r" in token):
        raise ValueError("invalid bearer credential")
    if token and not secure:
        raise ValueError("bearer credentials require a secure endpoint")
    if (credentials.certificate_chain is None) != (credentials.private_key is None):
        raise ValueError("certificate_chain and private_key must be supplied together")


class Client:
    """Async remote client with Rust-selected secure transport defaults."""

    def __init__(self, endpoint: str, credentials: Credentials | None = None):
        self.credentials = credentials or Credentials()
        target, secure = _target(endpoint)
        _validate(self.credentials, secure)
        call_credentials = None
        if self.credentials.bearer_token:
            call_credentials = grpc.access_token_call_credentials(self.credentials.bearer_token)
        if secure:
            ssl_credentials = grpc.ssl_channel_credentials(
                root_certificates=self.credentials.root_certificates,
                private_key=self.credentials.private_key,
                certificate_chain=self.credentials.certificate_chain,
            )
            channel_credentials = (
                grpc.composite_channel_credentials(ssl_credentials, call_credentials)
                if call_credentials is not None
                else ssl_credentials
            )
            self._channel = grpc.aio.secure_channel(target, channel_credentials)
        else:
            self._channel = grpc.aio.insecure_channel(target)
        self.actors = actors_pb2_grpc.ActorsServiceStub(self._channel)
        self.stream = stream_pb2_grpc.StreamServiceStub(self._channel)
        self.buckets = objects_pb2_grpc.BucketsServiceStub(self._channel)
        self.objects = objects_pb2_grpc.ObjectsServiceStub(self._channel)
        self.workers = workers_pb2_grpc.WorkersServiceStub(self._channel)
        self.filesystem = filesystem_pb2_grpc.FilesystemServiceStub(self._channel)
        self.harness = harness_pb2_grpc.HarnessServiceStub(self._channel)
        self.inference = InferenceServices(
            models=inference_pb2_grpc.ModelsServiceStub(self._channel),
            contexts=inference_pb2_grpc.ContextsServiceStub(self._channel),
            warm_contexts=inference_pb2_grpc.WarmContextsServiceStub(self._channel),
            runs=inference_pb2_grpc.RunsServiceStub(self._channel),
            evaluations=inference_pb2_grpc.EvaluationsServiceStub(self._channel),
        )
        self.machines = machines_pb2_grpc.MachinesServiceStub(self._channel)

    async def close(self) -> None:
        await self._channel.close()

    async def __aenter__(self) -> "Client":
        return self

    async def __aexit__(self, exc_type, exc_value, traceback) -> None:
        await self.close()


__all__ = ["BEST_TRANSPORT", "Client", "Credentials", "InferenceServices", "OPERATIONS", "SOURCE_BINDING"]


OPERATIONS = {
#OPERATIONS#
}


TRANSPORTS = {
#TRANSPORTS#
}
"###,
    );
    output = output.replace("#BINDING#", binding);
    output = output.replace("#OPERATIONS#", &python_operations());
    output = output.replace("#TRANSPORTS#", &python_transports());
    output
}

